for tr,r0 in enumerate(st):
 for tc,c0 in enumerate(st):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n: g[r][c]=4 if dr in (0,4) or dc in (0,4) else vals[tr][tc]
def paint(rows,cols,color):
 for r in rows:
  for c in cols:
   if 0<=r<n and 0<=c<n and g[r][c]==0:g[r][c]=color
# 3-colored motifs: rows of tiles 0 and 2, columns 0 and 3
for tr in (0,2):
 paint(range(st[tr]+1,st[tr]+4), [c for tc in range(3) for c in (st[tc]+5,st[tc]+6)],3)
for tc in (0,3):
 paint([r for tr in range(2) for r in (st[tr]+5,st[tr]+6)], range(st[tc]+1,st[tc]+4),3)
# 8-colored motifs: rows 1 and 3, columns 1 and 2
for tr in (1,3):
 paint(range(st[tr]+1,st[tr]+4), [st[1]+5,st[1]+6],8)
for tc in (1,2):
 paint([r for tr in range(1,3) for r in (st[tr]+5,st[tr]+6)], range(st[tc]+1,st[tc]+4),8)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

import json
n=30; starts=[1,8,15,22,29]
g=[[0]*n for _ in range(n)]
# Interior colors for each 5x5 tile (the final partial tile at row/col 29 has only border visible).
vals=[[3,2,2,3,0],[2,8,8,2,0],[3,2,2,3,0],[2,8,8,2,0],[0,0,0,0,0]]
for tr,r0 in enumerate(starts):
 for tc,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<n and c<n:
     g[r][c]=4 if dr in (0,4) or dc in (0,4) else vals[tr][tc]
# Horizontal connectors: extend each repeated special interior patch only through intervening zero gutters.
def hconnect(tile_row, first_col, last_col, color):
 r0=starts[tile_row]
 for r in range(r0+1,r0+4):
  for tc in range(first_col,last_col):
   for c in (starts[tc]+5,starts[tc]+6):
    if c<n and g[r][c]==0:g[r][c]=color
def vconnect(tile_col, first_row, last_row, color):
 c0=starts[tile_col]
 for c in range(c0+1,c0+4):
  for tr in range(first_row,last_row):
   for r in (starts[tr]+5,starts[tr]+6):
    if r<n and g[r][c]==0:g[r][c]=color
# 3 patches align in tile rows 0,2 and tile columns 0,3.
for tr in (0,2): hconnect(tr,0,3,3)
for tc in (0,3): vconnect(tc,0,2,3)
# 8 patches align in tile rows 1,3 and tile columns 1,2.
for tr in (1,3): hconnect(tr,1,2,8)
for tc in (1,2): vconnect(tc,1,3,8)
